    """
    Evaluates an arithmetic expression using the Shunting Yard algorithm 
    followed by Reverse Polish Notation (RPN) for computation. 
    Supports +, -, *, /, parentheses, and floating-point numbers. 
    Respects standard operator precedence.
    """
    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators: list, values: list) -> None:
        right = values.pop()
        left = values.pop()
        op = operators.pop()

        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            values.append(left / right)

    def shunting_yard(expression: str) -> list:
        output = []
        operators = []
        num = ''

        for char in expression:
            if char.isdigit() or char == '.':
                num += char
            else:
                if num:
                    output.append(float(num))
                    num = ''
                if char in '+-*/':
                    while (operators and 
                           precedence(operators[-1]) >= precedence(char)):
                        apply_operator(operators, output)
                    operators.append(char)
                elif char == '(':
                    operators.append(char)
                elif char == ')':
                    while operators and operators[-1] != '(':
                        apply_operator(operators, output)
                    operators.pop()  # Pop the '('

        if num:
            output.append(float(num))

        while operators:
            apply_operator(operators, output)

        return output

    tokens = shunting_yard(expr.replace(' ', ''))
    return tokens[0] if tokens else 0

