def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using a recursive descent parsing technique.
    The approach builds an Abstract Syntax Tree (AST) for the expression and evaluates it
    recursively. Supports +, -, *, /, parentheses, and floating-point numbers.
    Respects standard operator precedence.
    """

    class Token:
        NUMBER, PLUS, MINUS, TIMES, DIVIDE, LPAREN, RPAREN = 'NUMBER', 'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'LPAREN', 'RPAREN'

    def tokenize(expression: str):
        tokens = []
        value = ''
        for char in expression:
            if char.isdigit() or char == '.':
                value += char
            else:
                if value:
                    tokens.append((Token.NUMBER, float(value)))
                    value = ''
                if char == '+':
                    tokens.append((Token.PLUS,))
                elif char == '-':
                    tokens.append((Token.MINUS,))
                elif char == '*':
                    tokens.append((Token.TIMES,))
                elif char == '/':
                    tokens.append((Token.DIVIDE,))
                elif char == '(':
                    tokens.append((Token.LPAREN,))
                elif char == ')':
                    tokens.append((Token.RPAREN,))
        if value:
            tokens.append((Token.NUMBER, float(value)))
        return tokens

    def parse_expression(index):
        left_value, index = parse_term(index)
        while index < len(tokens):
            token = tokens[index]
            if token[0] in (Token.PLUS, Token.MINUS):
                index += 1
                right_value, index = parse_term(index)
                if token[0] == Token.PLUS:
                    left_value += right_value
                else:
                    left_value -= right_value
            else:
                break
        return left_value, index

    def parse_term(index):
        left_value, index = parse_factor(index)
        while index < len(tokens):
            token = tokens[index]
            if token[0] in (Token.TIMES, Token.DIVIDE):
                index += 1
                right_value, index = parse_factor(index)
                if token[0] == Token.TIMES:
                    left_value *= right_value
                else:
                    left_value /= right_value
            else:
                break
        return left_value, index

    def parse_factor(index):
        token = tokens[index]
        if token[0] == Token.NUMBER:
            return token[1], index + 1
        elif token[0] == Token.LPAREN:
            index += 1
            result, index = parse_expression(index)
            if tokens[index][0] != Token.RPAREN:
                raise ValueError("Mismatched parentheses")
            return result, index + 1
        raise ValueError("Unexpected token")

